import {escapeHtml as esc} from './message-format.js';
import {localAt,addDays} from './oncall-planning.js';
import {generateRegionalPlan,continueRegionalRecipe} from './oncall-regional.js';
const zoneList=['UTC','Europe/Zurich','Europe/London','America/New_York','America/Los_Angeles','Asia/Singapore','Australia/Sydney'];
const clock=m=>`${String(Math.floor(Number(m)/60)).padStart(2,'0')}:${String(Number(m)%60).padStart(2,'0')}`;
export function regionalEditor({root,w,saved,run,api,token,requestKey,status}){
 const last=w.plans.filter(p=>p.published).sort((a,b)=>a.endAt>b.endAt?-1:1)[0],zone=saved?.recipe.timezone||last?.timezone||'UTC';
 const priorEnd=last&&Number(last.endAt/1000000n)>Date.now()?localAt(Number(last.endAt/1000000n),zone):null;
 const start=priorEnd?(priorEnd.slice(11)==='00:00'?priorEnd.slice(0,10):addDays(priorEnd.slice(0,10),1)):addDays(localAt(Date.now(),zone).slice(0,10),1);
 const makeRegion=(name,timezone)=>({name,timezone,startMinute:480n,endMinute:1200n,days:[0n,1n,2n,3n,4n,5n,6n],holidays:[],primary:[],backup:[],backupMode:{none:null}});
 let recipe=saved?continueRegionalRecipe(saved.recipe,start):{startDate:start,weeks:4n,timezone:zone,rotationDays:7n,requirement:{continuous:null},regions:[makeRegion('Europe','Europe/Zurich'),makeRegion('Americas','America/Los_Angeles')]};
 root.innerHTML=`<a class="back-link" href="#/oncall/${w.project.id}">← ${esc(w.project.name)}</a><div class="page-heading"><div><span class="eyebrow">REGIONAL COVERAGE</span><h2>One team. Across time zones.</h2><p class="lead">Local hours, clear handoffs and one shared coverage plan.</p></div><a class="button" href="#/oncall/${w.project.id}/simple-new">Use one rotation</a></div>${saved?`<p class="oc-footnote">Previous regional rules carried forward. ${saved.edited?'The last plan had manual assignments; these are not repeated. ':''}Review holiday dates and who starts each rotation.</p>`:''}<form id="regionalForm"><section class="card oc-form"><div class="row"><div><label for="regionalStart">First day</label><input id="regionalStart" type="date" value="${esc(recipe.startDate)}" required></div><div><label for="regionalWeeks">Plan ahead</label><select id="regionalWeeks">${[1,2,4,8,12].map(n=>`<option value="${n}" ${Number(recipe.weeks)===n?'selected':''}>${n} ${n===1?'week':'weeks'}</option>`).join('')}</select></div><div><label for="regionalRotation">Change responder</label><select id="regionalRotation"><option value="7">Every week</option><option value="1" ${recipe.rotationDays===1n?'selected':''}>Every day</option></select></div></div><div class="row"><div><label for="regionalZone">Plan boundary & review timezone</label><input type="text" id="regionalZone" value="${esc(recipe.timezone)}" list="regionalZones" required></div><div><label for="regionalRequirement">Required primary coverage</label><select id="regionalRequirement"><option value="continuous">24/7 · flag every gap</option><option value="regional" ${Object.hasOwn(recipe.requirement,'regional')?'selected':''}>Only the regional hours below</option></select></div></div><p class="kv">The period starts and ends at midnight in the review timezone. Regions keep their own local hours across clock changes.</p></section><datalist id="regionalZones">${zoneList.map(z=>`<option value="${z}">`).join('')}</datalist><div class="section-heading"><div><h3>Regions in handoff order</h3><p class="kv">When hours overlap, the earlier region stays responsible. The preview shows the hours this removes from later regions.</p></div><button id="addRegion" type="button">Add region ＋</button></div><div id="regionalCards" class="oc-regions"></div><div class="oc-editor-footer"><button class="primary" type="submit">Preview handoffs →</button>${status}</div><div id="regionalPreview"></div></form>`;
 const preview=()=>root.querySelector('#regionalPreview').replaceChildren();
 const capture=()=>{
  recipe.startDate=root.querySelector('#regionalStart').value;recipe.weeks=BigInt(root.querySelector('#regionalWeeks').value);recipe.rotationDays=BigInt(root.querySelector('#regionalRotation').value);recipe.timezone=root.querySelector('#regionalZone').value.trim();recipe.requirement={[root.querySelector('#regionalRequirement').value]:null};
  root.querySelectorAll('[data-region]').forEach(card=>{const r=recipe.regions[Number(card.dataset.region)],v=key=>card.querySelector('[data-field="'+key+'"]').value;const minutes=s=>{if(!/^\d{2}:\d{2}$/.test(s))throw Error('Complete the regional start and end times before changing the rotation.');const[a,b]=s.split(':').map(Number);return BigInt(a*60+b);};r.name=v('name').trim();r.timezone=v('zone').trim();r.startMinute=minutes(v('start'));r.endMinute=v('end')==='00:00'?1440n:minutes(v('end'));r.days=v('days')==='all'?[0n,1n,2n,3n,4n,5n,6n]:[1n,2n,3n,4n,5n];r.holidays=v('holidays').split(',').map(s=>s.trim()).filter(Boolean);r.backupMode={[v('backupMode')]:null};});
 };
 function captureSafe(){try{capture();return true;}catch(error){root.querySelector('[data-oc-status]').textContent=error.message;return false;}}
 function paint(){
  root.querySelector('#addRegion').disabled=recipe.regions.length>=3;
  root.querySelector('#regionalCards').innerHTML=recipe.regions.map((r,i)=>`<section class="card oc-form" data-region="${i}"><div class="section-heading"><span class="eyebrow">${String(i+1).padStart(2,'0')} · REGION</span><div>${i?'<button type="button" data-up>Move earlier ↑</button>':''}${recipe.regions.length>1?'<button type="button" data-remove>Remove</button>':''}</div></div><label for="r${i}name">Name</label><input type="text" id="r${i}name" data-field="name" value="${esc(r.name)}" maxlength="40" required><label for="r${i}zone">Local timezone</label><input type="text" id="r${i}zone" data-field="zone" value="${esc(r.timezone)}" list="regionalZones" required><div class="row"><div><label for="r${i}start">From</label><input id="r${i}start" data-field="start" type="time" value="${clock(r.startMinute)}" required></div><div><label for="r${i}end">Until · next day if earlier</label><input id="r${i}end" data-field="end" type="time" value="${clock(r.endMinute===1440n?0n:r.endMinute)}" required></div></div><label for="r${i}days">Primary days</label><select id="r${i}days" data-field="days"><option value="all">Every day</option><option value="weekdays" ${r.days.length===5?'selected':''}>Monday–Friday</option></select><label>Primary rotation · select in order</label><div data-roster="primary"></div><details class="oc-backup"><summary>Backups & holidays</summary><label for="r${i}mode">Backup coverage · same local hours</label><select id="r${i}mode" data-field="backupMode"><option value="none">No backup</option><option value="always" ${Object.hasOwn(r.backupMode,'always')?'selected':''}>Same days as primary</option><option value="nonworking" ${Object.hasOwn(r.backupMode,'nonworking')?'selected':''}>Weekends & listed holidays</option></select><div data-roster="backup"></div><label for="r${i}holidays">Dates without primary coverage</label><input type="text" id="r${i}holidays" data-field="holidays" value="${esc(r.holidays.join(', '))}" placeholder="2026-12-25, 2027-01-01"><p class="kv">Regional dates, comma separated. A holiday omits primary hours and enables weekend/holiday backup. It does not promote backup to primary or set pay rates.</p></details></section>`).join('');
  root.querySelectorAll('[data-region]').forEach(card=>{const i=Number(card.dataset.region),r=recipe.regions[i];
   for(const kind of ['primary','backup']){const box=card.querySelector('[data-roster="'+kind+'"]'),missing=r[kind].filter(id=>!w.members.some(m=>m.id===id));box.innerHTML=`<div class="oc-people">${[...w.members,...missing.map(id=>({id,name:'No longer eligible · remove'}))].map(m=>{const n=r[kind].indexOf(m.id);return`<button type="button" class="oc-person ${n>=0?'selected':''}" aria-pressed="${n>=0}" data-person="${esc(m.id)}"><span class="oc-order">${n>=0?n+1:'＋'}</span>${esc(m.name)}</button>`;}).join('')}</div>`;box.querySelectorAll('[data-person]').forEach(b=>b.onclick=()=>{if(!captureSafe())return;r[kind]=r[kind].includes(b.dataset.person)?r[kind].filter(id=>id!==b.dataset.person):[...r[kind],b.dataset.person];preview();paint();});}
   const up=card.querySelector('[data-up]');if(up)up.onclick=()=>{if(!captureSafe())return;[recipe.regions[i-1],recipe.regions[i]]=[recipe.regions[i],recipe.regions[i-1]];preview();paint();};
   const remove=card.querySelector('[data-remove]');if(remove)remove.onclick=()=>{if(!captureSafe())return;recipe.regions.splice(i,1);preview();paint();};
  });
 }
 paint();root.querySelector('#addRegion').onclick=()=>{if(!captureSafe())return;recipe.regions.push(makeRegion('Asia Pacific','Asia/Singapore'));preview();paint();};
 root.querySelector('#regionalForm').addEventListener('input',preview);root.querySelector('#regionalForm').addEventListener('change',preview);
 root.querySelector('#regionalForm').onsubmit=e=>{e.preventDefault();try{capture();if(recipe.regions.some(r=>[...r.primary,...r.backup].some(id=>!w.members.some(m=>m.id===id))))throw Error('Remove people who no longer have project access before continuing.');const {input,summary}=generateRegionalPlan(w.project.id,recipe),snapshot=structuredClone(recipe),box=root.querySelector('#regionalPreview');box.innerHTML=`<section class="card oc-form"><span class="eyebrow">HANDOFF PREVIEW</span><h3>${summary.missingHours>0?`${summary.missingHours.toFixed(1)} primary hours need coverage`:'Required primary hours covered'}</h3>${summary.missingHours>0?'<p class="oc-issues">The exact gaps appear in the saved draft. Publishing them requires explicit acknowledgement.</p>':''}<div class="table-scroll"><table><thead><tr><th>Region</th><th>Primary duty</th><th>Overlap kept by earlier region</th></tr></thead><tbody>${snapshot.regions.map((r,i)=>`<tr><td>${esc(r.name)}<span class="rowsub">${esc(r.timezone)}</span></td><td>${summary.hours[i].toFixed(1)} h</td><td>${summary.overlapHours[i].toFixed(1)} h</td></tr>`).join('')}</tbody></table></div><p class="kv">${input.shifts.length} duty intervals. These are elapsed planned hours, not approved work or pay. Every date and assignment remains reviewable in the draft.</p><button type="button" class="primary" id="saveRegional">Save draft & review dates →</button></section>`;box.querySelector('#saveRegional').onclick=event=>run(event.currentTarget,()=>api().saveOncallRegionalPlan(token(),0n,0n,requestKey,input,snapshot),result=>{location.hash=`#/oncall/${w.project.id}/${result.id}`;});root.querySelector('[data-oc-status]').textContent='';box.scrollIntoView?.({block:'start'});}catch(error){root.querySelector('[data-oc-status]').textContent=error.message;}};
}
